function parseA1(range) {
  if (typeof range !== "string") return null;
  const index = range.lastIndexOf("!");
  if (index < 1) return null;
  const spelling = range.slice(0, index);
  const tab =
    spelling.startsWith("'") && spelling.endsWith("'")
      ? spelling.slice(1, -1).replace(/''/g, "'")
      : spelling;
  const cells = range
    .slice(index + 1)
    .replace(/\$/g, "")
    .toUpperCase();
  return { tab, cells };
}

function checkedRows(page, tab, headers) {
  const got = parseA1(page.range);
  const rows = page.values ?? [];
  if (
    got?.tab !== tab ||
    !/^A(?:1)?(?::Z\d*)?$/.test(got.cells) ||
    page.majorDimension !== "ROWS" ||
    !Array.isArray(rows) ||
    rows.some((row) => !Array.isArray(row))
  ) {
    throw new Error("Sheets did not return the configured tab in row order.");
  }
  if (!rows.length) return null;
  if (headers.some((heading, i) => rows[0][i] !== heading))
    throw new Error("Check the required headings in " + tab + ".");
  return rows.slice(1);
}

function contactKey(value, keyColumn) {
  if (keyColumn === "id" && Number.isSafeInteger(value)) return String(value);
  if (typeof value !== "string" || !value.trim() || value.startsWith("=")) return null;
  return keyColumn === "email" ? value.toLowerCase() : value;
}

function cleanContacts(config, page, timestamp) {
  const headings = ["id", "name", "email", "status"];
  const rows = checkedRows(page, config.sourceTab, headings) ?? [];
  const keyIndex = headings.indexOf(config.keyColumn);
  const seen = new Set();
  const clean = [];
  for (const raw of rows) {
    const name = raw[1] ? String(raw[1]).trim() : "";
    const email = raw[2] ? String(raw[2]).toLowerCase() : "";
    if (!name || !email.trim()) continue;
    const next = [raw[0] ?? "", name, email, raw[3] || "pending", timestamp, true];
    const key = contactKey(next[keyIndex], config.keyColumn);
    if (key === null || seen.has(key))
      throw new Error(
        "The source contains a missing, invalid or duplicate " + config.keyColumn + " match key.",
      );
    seen.add(key);
    clean.push(next);
  }
  return { rows: clean, timestamp };
}
export default ({ config, ...page }) => {
  const clean = cleanContacts(config, page, new Date().toISOString());
  return { clean, hasRows: clean.rows.length > 0 };
};

