    page.majorDimension !== "ROWS" ||
    !Array.isArray(rows) ||
    rows.some((row) => !Array.isArray(row))
  ) {
    throw new Error("Sheets did not return the configured tab in row order.");
  }
  if (!rows.length) return null;
  if (headers.some((heading, i) => rows[0][i] !== heading))
