function contactKey(value, keyColumn) {
  if (keyColumn === "id" && Number.isSafeInteger(value)) return String(value);
  if (typeof value !== "string" || !value.trim() || value.startsWith("=")) return null;
  return keyColumn === "email" ? value.toLowerCase() : value;
}

function planContacts(config, clean, page) {
  const headers = ["id", "name", "email", "status", "created_at", "processed"];
  const rows = checkedRows(page, config.targetTab, headers);
  if (rows === null) throw new Error("Add the target headers before running.");
  const keyIndex = headers.indexOf(config.keyColumn);
  const byKey = new Map();
  for (const [i, row] of rows.entries()) {
    if (row.every((cell) => cell === null || cell === undefined || cell === "")) continue;
    const key = contactKey(row[keyIndex], config.keyColumn);
    if (key === null || byKey.has(key))
      throw new Error(
        "The target contains a missing, invalid or duplicate " + config.keyColumn + " match key.",
      );
    byKey.set(key, i + 2);
  }
  let next = rows.length + 2;
  let updated = 0;
  const data = clean.rows.map((values) => {
    const key = contactKey(values[keyIndex], config.keyColumn);
    let row = byKey.get(key);
    if (row === undefined) row = next++;
    else updated++;
    return {
      range: config.targetPrefix + "!A" + row + ":F" + row,
      majorDimension: "ROWS",
      values: [values],
    };
  });
  return { data, updated, inserted: data.length - updated, timestamp: clean.timestamp };
}
export default ({ config, clean, ...page }) => {
  const plan = planContacts(config, clean, page);
  return { plan, data: plan.data };
};

