function confirmContactWrites(config, plan, receipt) {
  const { spreadsheetId, totalUpdatedRows, totalUpdatedCells, responses } = receipt;
  if (
    spreadsheetId !== config.targetId ||
    totalUpdatedRows !== plan.data.length ||
    totalUpdatedCells !== 6 * plan.data.length ||
    !Array.isArray(responses) ||
    responses.length !== plan.data.length
  ) {
    throw new Error(
      "Sheets did not confirm the full update. Check the target before running again.",
    );
  }
  for (const [i, expected] of plan.data.entries()) {
    const got = responses[i],
      range = parseA1(expected.range),
      updated = parseA1(got?.updatedRange),
      result = parseA1(got?.updatedData?.range);
    if (
      updated?.tab !== range.tab ||
      updated.cells !== range.cells ||
      result?.tab !== range.tab ||
      result.cells !== range.cells ||
      got.updatedRows !== 1 ||
      got.updatedCells !== 6 ||
      JSON.stringify(got.updatedData?.values) !== JSON.stringify(expected.values)
    ) {
      throw new Error(
        "Sheets did not confirm each requested row. Check the target before running again.",
      );
    }
  }
  return {
    summary: "Data processing completed successfully",
    processed_count: totalUpdatedRows,
    updated_count: plan.updated,
    inserted_count: plan.inserted,
    timestamp: plan.timestamp,
  };
}
export default ({ config, plan, ...receipt }) => ({
  summary: confirmContactWrites(config, plan, receipt),
});

